catalog_script_client.script:
function onLoad() {
    console.log('Client Script onLoad executed');

    // Get the current user name
    var currentUser = g_user.userName;
    console.log('Current user:', currentUser);

    // If the current user is not defined, log an error and exit
    if (!currentUser) {
        console.error('Current user is not defined');
        return;
    }

    // Create a new GlideAjax object for the Script Include 'InvoiceDateHelfer'
    var ga = new GlideAjax('InvoiceDateHelfer');
    ga.addParam('sysparm_name', 'getAvailableYearsAndMonths');
    ga.addParam('sysparm_userName', currentUser);

    console.log('Sending parameters to Script Include:', {
        sysparm_name: 'getAvailableYearsAndMonths',
        sysparm_userName: currentUser
    });

    // Call the Script Include and process the response
    ga.getXMLAnswer(processResponse);
}

function processResponse(response) {
    console.log('Response received from server:', response); // Log the raw response

    // Parse the JSON response from the Script Include
    var result = JSON.parse(response);
    console.log('Available years and dates:', result);

    // Get the controls for the dropdowns by their Sys IDs
    var yearDropdown = g_form.getControl('IO:e464b22c1bb4d2103f86b9118b4bcbda');
    var dateDropdown = g_form.getControl('IO:f994b62c1bb4d2103f86b9118b4bcbb7');

    // Update the year dropdown with the available years
    updateDropdown(yearDropdown, result.years);

    // Add an event listener to the year dropdown to update dates based on selected year
    yearDropdown.addEventListener('change', function() {
        var selectedYear = yearDropdown.value;
        console.log('Year dropdown changed to:', selectedYear); // Log the selected year
        updateDatesDropdown(dateDropdown, result.dates, selectedYear);
    });

    // Initialize the dates dropdown based on the initially selected year
    var initialYear = yearDropdown.value;
    console.log('Initializing dates dropdown for year:', initialYear);
    updateDatesDropdown(dateDropdown, result.dates, initialYear);
}

function updateDropdown(dropdown, values) {
    // Remove all existing options from the dropdown
    while (dropdown.options.length > 0) {
        dropdown.remove(0);
    }

    console.log('Updating dropdown with values:', values);

    // Add new options to the dropdown based on the values array
    values.forEach(function(value) {
        var option = new Option(value, value);
        dropdown.add(option);
    });

    console.log('Updated dropdown options:', Array.from(dropdown.options).map(option => option.value));
}

function updateDatesDropdown(dateDropdown, datesData, selectedYear) {
    // Filter the dates based on the selected year
    var filteredDates = datesData[selectedYear] || [];
    console.log('Filtered dates for year ' + selectedYear + ':', filteredDates); // Log filtered dates

    // Update the date dropdown with the filtered dates
    updateDropdown(dateDropdown, filteredDates);
}
